import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import DashboardPage from './pages/DashboardPage';
import MapsPage from './pages/MapsPage';
import KnowledgeHubPage from './pages/KnowledgeHubPage';
import NewsAndInsightsPage from './pages/NewsAndInsightsPage';
import SourcingHubPage from './pages/SourcingHubPage';
import AddOfferPage from './pages/AddOfferPage';
import SupportPage from './pages/SupportPage';
import Navbar from './components/Navbar';
import Footer from './components/Footer';

function App() {
  const [user, setUser] = useState(null);

  const handleNavigate = (page) => {
    window.location.href = `/${page}`;
  };

  return (
    <Router>
      <Navbar user={user} onNavigate={handleNavigate} />
      <Routes>
        <Route path="/" element={<LoginPage onNavigate={handleNavigate} />} />
        <Route path="/register" element={<RegisterPage onNavigate={handleNavigate} />} />
        <Route path="/dashboard" element={<DashboardPage onNavigate={handleNavigate} />} />
        <Route path="/maps" element={<MapsPage />} />
        <Route path="/knowledgeHub" element={<KnowledgeHubPage onNavigate={handleNavigate} />} />
        <Route path="/newsAndInsights" element={<NewsAndInsightsPage onNavigate={handleNavigate} />} />
        <Route path="/sourcingHub" element={<SourcingHubPage onNavigate={handleNavigate} />} />
        <Route path="/addOffer" element={<AddOfferPage onNavigate={handleNavigate} user={user} />} />
        <Route path="/support" element={<SupportPage user={user} />} />
      </Routes>
      <Footer />
    </Router>
  );
}

export default App;
